"""
Prefix-cache-oriented dataframe column permutation optimizer.

This implementation preserves every dataframe cell, row, index, column label,
and shape.  It evaluates a bounded number of candidate column-ordering
constructions using the exact serial-Trie reuse objective: the sum of LCPs
between lexicographically adjacent serialized rows.

Candidates:
1. Global order ranked by length-weighted repeated-value pair frequency.
2. Global order ranked by exact per-field standalone prefix-Trie reuse.
3. A shallow conditional prefix partition tree using local repeated-value
   savings, followed by a deterministic global suffix order.

The best candidate is selected by the actual full-row Trie objective.
"""

from collections import Counter, defaultdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded dataframe column-permutation optimizer for prefix-cache reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store an optional dataframe reference without modifying it."""
        self.df = df

    @staticmethod
    def _cell_string(value) -> str:
        """Return evaluator-compatible serialized text without changing stored data."""
        if value is None:
            return ""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute a string LCP with logarithmically many C-level slice comparisons."""
        limit = min(len(left), len(right))
        if not limit:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    def _trie_score(self, strings: List[str]) -> int:
        """Return exact ideal serial-Trie reuse for a fixed collection of strings."""
        if len(strings) < 2:
            return 0

        strings.sort()
        total = 0
        previous = strings[0]
        for current in strings[1:]:
            total += self._lcp(previous, current)
            previous = current
        return total

    def _standalone_score(self, values: List[str]) -> int:
        """Score a single field's serialized values using the exact Trie objective."""
        return self._trie_score(values[:])

    @staticmethod
    def _normalize_groups(col_merge) -> List[List]:
        """Normalize merge declarations into nonempty lists."""
        if not col_merge:
            return []
        output = []
        for group in col_merge:
            if isinstance(group, (tuple, list)):
                if group:
                    output.append(list(group))
            else:
                output.append([group])
        return output

    @staticmethod
    def _build_units(
        columns: List,
        col_merge,
        dependencies,
    ) -> Tuple[List[List[int]], Dict[int, set]]:
        """Create indivisible merge units and unit-level dependency predecessors."""
        by_name = defaultdict(list)
        for position, name in enumerate(columns):
            by_name[name].append(position)

        units = []
        used = set()

        for group in Evolved._normalize_groups(col_merge):
            positions = []
            for name in group:
                for position in by_name.get(name, []):
                    if position not in used:
                        positions.append(position)
                        used.add(position)
            if positions:
                units.append(positions)

        for position in range(len(columns)):
            if position not in used:
                units.append([position])

        unit_for_position = {}
        for unit_id, unit in enumerate(units):
            for position in unit:
                unit_for_position[position] = unit_id

        predecessors = {unit: set() for unit in range(len(units))}
        for edge in dependencies or []:
            if not isinstance(edge, (tuple, list)) or len(edge) < 2:
                continue
            before, after = edge[0], edge[1]
            for left_position in by_name.get(before, []):
                for right_position in by_name.get(after, []):
                    left = unit_for_position[left_position]
                    right = unit_for_position[right_position]
                    if left != right:
                        predecessors[right].add(left)

        return units, predecessors

    @staticmethod
    def _topological_priority_order(
        unit_count: int,
        predecessors: Dict[int, set],
        priority: List[int],
    ) -> List[int]:
        """Return deterministic priority-biased topological order, breaking cycles safely."""
        priority_rank = {unit: rank for rank, unit in enumerate(priority)}
        remaining = set(range(unit_count))
        done = set()
        output = []

        while remaining:
            available = [
                unit for unit in remaining
                if predecessors.get(unit, set()).issubset(done)
            ]
            if not available:
                available = list(remaining)

            chosen = min(
                available,
                key=lambda unit: (priority_rank.get(unit, unit_count), unit),
            )
            output.append(chosen)
            remaining.remove(chosen)
            done.add(chosen)

        return output

    @staticmethod
    def _factorize(values: List[str]) -> Tuple[List[int], List[int], List[int]]:
        """Factorize strings into row codes, code lengths, and code frequencies."""
        mapping = {}
        codes = []
        lengths = []
        counts = []

        for value in values:
            code = mapping.get(value)
            if code is None:
                code = len(lengths)
                mapping[value] = code
                lengths.append(len(value))
                counts.append(0)
            codes.append(code)
            counts[code] += 1

        return codes, lengths, counts

    @staticmethod
    def _pair_score(lengths: List[int], counts: List[int]) -> int:
        """Return length-weighted repeated-value pair score for one field unit."""
        return sum(
            length * count * (count - 1)
            for length, count in zip(lengths, counts)
            if length and count > 1
        )

    @staticmethod
    def _serialize_global(
        unit_values: List[List[str]],
        order: List[int],
        n_rows: int,
    ) -> List[str]:
        """Serialize every row under one shared unit order."""
        return [
            "".join(unit_values[unit][row] for unit in order)
            for row in range(n_rows)
        ]

    @staticmethod
    def _serialize_orders(
        unit_values: List[List[str]],
        orders: List[List[int]],
    ) -> List[str]:
        """Serialize rows under independently selected per-row unit orders."""
        return [
            "".join(unit_values[unit][row] for unit in order)
            for row, order in enumerate(orders)
        ]

    def _conditional_candidate(
        self,
        codes_by_unit: List[List[int]],
        lengths_by_unit: List[List[int]],
        suffix_order: List[int],
        predecessors: Dict[int, set],
        early_stop,
        col_stop,
    ) -> List[List[int]]:
        """
        Build a shallow conditional prefix tree using local repeated-value savings.

        Each active row group chooses one legal remaining leading unit based on
        length-weighted repeated code pairs.  Rows are partitioned by that
        unit's value, then receive the deterministic global suffix order.
        """
        unit_count = len(codes_by_unit)
        n_rows = len(codes_by_unit[0]) if unit_count else 0
        orders = [[] for _ in range(n_rows)]

        if n_rows < 2 or unit_count < 2:
            return [suffix_order[:] for _ in range(n_rows)]

        candidate_limit = min(12, unit_count)
        candidate_set = set(suffix_order[:candidate_limit])

        changed = True
        while changed:
            changed = False
            for unit in tuple(candidate_set):
                for predecessor in predecessors.get(unit, ()):
                    if predecessor not in candidate_set:
                        candidate_set.add(predecessor)
                        changed = True

        candidates = [unit for unit in suffix_order if unit in candidate_set]
        depth = min(4, len(candidates))

        if col_stop is not None:
            try:
                stop = int(col_stop)
                if stop > 0:
                    depth = min(depth, stop)
            except Exception:
                pass

        try:
            threshold = max(0, int(early_stop or 0))
        except Exception:
            threshold = 0

        groups = [(list(range(n_rows)), frozenset())]

        for _ in range(depth):
            next_groups = []
            progressed = False

            for rows, completed in groups:
                if len(rows) < 2:
                    next_groups.append((rows, completed))
                    continue

                available = [
                    unit for unit in candidates
                    if unit not in completed
                    and predecessors.get(unit, set()).issubset(completed)
                ]
                if not available:
                    next_groups.append((rows, completed))
                    continue

                best_unit = None
                best_score = threshold

                for unit in available:
                    local = Counter(codes_by_unit[unit][row] for row in rows)
                    lengths = lengths_by_unit[unit]
                    score = sum(
                        lengths[code] * count * (count - 1)
                        for code, count in local.items()
                        if count > 1 and lengths[code]
                    )
                    if score > best_score or (
                        score == best_score
                        and best_unit is not None
                        and unit < best_unit
                    ):
                        best_score = score
                        best_unit = unit

                if best_unit is None:
                    next_groups.append((rows, completed))
                    continue

                progressed = True
                codes = codes_by_unit[best_unit]
                for row in rows:
                    orders[row].append(best_unit)

                partitions = defaultdict(list)
                for row in rows:
                    partitions[codes[row]].append(row)

                updated = frozenset(set(completed) | {best_unit})
                for partition in partitions.values():
                    next_groups.append((partition, updated))

            groups = next_groups
            if not progressed:
                break

        for row in range(n_rows):
            used = set(orders[row])
            orders[row].extend(unit for unit in suffix_order if unit not in used)

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """
        Return the best bounded prefix-cache ordering while preserving all cells.

        Three cheap constructions are considered when the dataframe is moderate
        in size.  Candidate selection always uses full serialized row strings,
        so partial-field and cross-field character-prefix reuse are included.
        """
        n_rows, n_cols = df.shape
        columns = list(df.columns)

        if n_rows == 0 or n_cols == 0:
            return df.copy(), [columns[:] for _ in range(n_rows)]

        raw_values = df.to_numpy(dtype=object, copy=False)
        units, predecessors = self._build_units(columns, col_merge, one_way_dep)

        cell_strings = [
            [self._cell_string(raw_values[row, column]) for row in range(n_rows)]
            for column in range(n_cols)
        ]

        unit_values = []
        codes_by_unit = []
        lengths_by_unit = []
        pair_scores = []

        for unit in units:
            if len(unit) == 1:
                values = cell_strings[unit[0]]
            else:
                values = [
                    "".join(cell_strings[column][row] for column in unit)
                    for row in range(n_rows)
                ]

            codes, lengths, counts = self._factorize(values)
            unit_values.append(values)
            codes_by_unit.append(codes)
            lengths_by_unit.append(lengths)
            pair_scores.append(self._pair_score(lengths, counts))

        pair_priority = sorted(
            range(len(units)),
            key=lambda unit: (-pair_scores[unit], unit),
        )
        pair_order = self._topological_priority_order(
            len(units), predecessors, pair_priority
        )

        # Exact standalone scores are useful on modest tables, but are avoided
        # on very wide/large inputs where their sorts are not worth the cost.
        bounded_search = (
            n_rows >= 2
            and len(units) >= 2
            and n_rows * len(units) <= 220000
            and n_rows <= 35000
        )

        candidates = [pair_order]

        if bounded_search:
            standalone_scores = [
                self._standalone_score(values)
                for values in unit_values
            ]
            prefix_priority = sorted(
                range(len(units)),
                key=lambda unit: (-standalone_scores[unit], -pair_scores[unit], unit),
            )
            prefix_order = self._topological_priority_order(
                len(units), predecessors, prefix_priority
            )
            if prefix_order != pair_order:
                candidates.append(prefix_order)

            conditional_orders = self._conditional_candidate(
                codes_by_unit,
                lengths_by_unit,
                pair_order,
                predecessors,
                early_stop,
                col_stop,
            )
        else:
            conditional_orders = None

        best_global_order = pair_order
        best_row_orders = None
        best_score = -1

        for order in candidates:
            score = self._trie_score(
                self._serialize_global(unit_values, order, n_rows)
            )
            if score > best_score:
                best_score = score
                best_global_order = order

        if conditional_orders is not None:
            conditional_score = self._trie_score(
                self._serialize_orders(unit_values, conditional_orders)
            )
            if conditional_score > best_score:
                best_row_orders = conditional_orders

        if best_row_orders is None:
            positions = [
                position
                for unit in best_global_order
                for position in units[unit]
            ]
            output = raw_values[:, positions].copy()
            one_order = [columns[position] for position in positions]
            column_orderings = [one_order[:] for _ in range(n_rows)]
        else:
            output = np.empty((n_rows, n_cols), dtype=object)
            column_orderings = []

            for row, order in enumerate(best_row_orders):
                positions = [
                    position
                    for unit in order
                    for position in units[unit]
                ]
                output[row, :] = raw_values[row, positions]
                column_orderings.append([columns[position] for position in positions])

        reordered = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )
        return reordered, column_orderings


