        # Exact standalone scores are useful on modest tables, but are avoided
        # on very wide/large inputs where their sorts are not worth the cost.
        bounded_search = (
            n_rows >= 2
            and len(units) >= 2
            and n_rows * len(units) <= 220000
            and n_rows <= 35000
        )

        candidates = [pair_order]

        if bounded_search:
            standalone_scores = [
                self._standalone_score(values)
                for values in unit_values
            ]
            prefix_priority = sorted(
                range(len(units)),
                key=lambda unit: (-standalone_scores[unit], -pair_scores[unit], unit),
            )
            prefix_order = self._topological_priority_order(
                len(units), predecessors, prefix_priority
            )
            if prefix_order != pair_order:
                candidates.append(prefix_order)

            conditional_orders = self._conditional_candidate(
                codes_by_unit,
                lengths_by_unit,
                pair_order,
                predecessors,
                early_stop,
                col_stop,
            )
        else:
            conditional_orders = None

        best_global_order = pair_order
        best_row_orders = None
        best_score = -1

        for order in candidates:
            score = self._trie_score(
                self._serialize_global(unit_values, order, n_rows)
            )
            if score > best_score:
                best_score = score
                best_global_order = order

        if conditional_orders is not None:
            conditional_score = self._trie_score(
                self._serialize_orders(unit_values, conditional_orders)
            )
            if conditional_score > best_score:
                best_row_orders = conditional_orders

        if best_row_orders is None:
            positions = [
                position
                for unit in best_global_order
                for position in units[unit]
            ]
            output = raw_values[:, positions].copy()
            one_order = [columns[position] for position in positions]
            column_orderings = [one_order[:] for _ in range(n_rows)]
        else:
            output = np.empty((n_rows, n_cols), dtype=object)
            column_orderings = []

            for row, order in enumerate(best_row_orders):
                positions = [
                    position
                    for unit in order
                    for position in units[unit]
                ]
                output[row, :] = raw_values[row, positions]
                column_orderings.append([columns[position] for position in positions])

        reordered = pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
            dtype=object,
        )
        return reordered, column_orderings


